import * as Sentry from '@sentry/nuxt';

export default defineEventHandler(event => {
  const id = getRouterParam(event, 'id');
  const active = Sentry.getActiveSpan();
  const root = active ? Sentry.getRootSpan(active) : undefined;
  const json = root ? Sentry.spanToJSON(root) : undefined;
  if (id === 'boom') {
    throw new Error('users-route-boom');
  }
  return { id, name: json?.description ?? null, source: (json?.data?.['sentry.source'] as string) ?? null };
});
